{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Foundation & Mobility",
      "weeks": 4,
      "focus": "Rebuild movement quality, core control and joint mobility while introducing light loading."
    },
    {
      "name": "Strength Development",
      "weeks": 4,
      "focus": "Progress multi-joint strength with controlled loading, prioritising safe spine mechanics and increased intensity."
    },
    {
      "name": "Strength Consolidation & Capacity",
      "weeks": 4,
      "focus": "Increase work capacity and consolidate strength gains with higher density and planned progression, preparing for long-term maintenance."
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Upper Strength",
      "Lower Strength (low spinal load)",
      "Mobility & Core / Conditioning",
      "Full-Body Hypertrophy (controlled loading)"
    ]
  },
  "non_negotiables": [
    "No heavy spinal loading",
    "No loaded spinal flexion",
    "Follow physio guidance regarding L4-L5 disc herniation",
    "Use neutral spine positions for all lifts",
    "Prioritise controlled tempo and bracing over maximal loads",
    "Include progressive warm-up before every session",
    "Stop and reassess if any radicular pain or return of symptoms"
  ]
}
